'use strict';
const A=SkyAnalytics,D=ERP_DATA;
let lab;try{lab=JSON.parse(localStorage.getItem(A.KEY));if(!lab||!lab.org)lab=A.initial()}catch{lab=A.initial()}
lab.installedOverrides??={};
let labTab='orders',labPage=1,labQuery='',fleetTab='jobs',horizon=24,outlookPart='housing',inventoryPreview=null;
const oldRender=render,oldActions=actions,oldDemand=demand,oldMarket=marketplace,oldSupplier=supplierWorkspace,oldData=data;
nav.splice(0,1,['Control tower','grid'],['Metrics & Forecasting','spark'],['Fleet & maintenance','plane']);nav.splice(nav.length-1,0,['ERP data room','file']);
function labSave(){lab.calendarBase=SkyCalendar.BASE;try{localStorage.setItem(A.KEY,JSON.stringify(lab))}catch{saved=false}}
function labEvent(text){audit(text);labSave();save();render();toast(text)}
function labGo(view){close();state.role='Buyer';state.view=view;save();labSave();render();window.scrollTo({top:0,behavior:'instant'})}
function orgName(){return lab.org==='OEM'?'Crestline Aerospace':'Westhaven Air'}
function forecastRows(){return D.orders.filter(o=>o.org===lab.org).map(o=>({o,f:A.forecast(D,lab,o,state)}))}
function labMetrics(items){return `<div class="metrics lab-metrics">${items.map(([label,value,note])=>`<div><span>${label}</span><strong>${value}<small>${note}</small></strong></div>`).join('')}</div>`}
function simNote(text='All records and outputs are synthetic. No company systems or trained AI are connected.'){return `<div class="simulation-note">${icon('spark')}<span>SIMULATED AI / ERP DEMO</span><p>${text}</p></div>`}
render=function(){if(state.view==='Overview')state.view='Control tower';oldRender();const breadcrumb=$('.breadcrumb');if(breadcrumb)breadcrumb.outerHTML=`<label class="org-select"><span class="sr-only">Planning organization</span><select id="organization" aria-label="Planning organization"><option value="OEM" ${lab.org==='OEM'?'selected':''}>OEM · Crestline Aerospace</option><option value="Airline" ${lab.org==='Airline'?'selected':''}>Airline · Westhaven Air</option></select></label>`;const workspaceLabel=$('.workspace-label');if(workspaceLabel)workspaceLabel.innerHTML=`<span class="workspace-mark">${lab.org==='OEM'?'C':'W'}</span><div>${orgName()}<small>${lab.org==='OEM'?'Production & procurement':'Fleet maintenance & sourcing'}</small></div>`;const strip=$('.demo-strip');if(strip)strip.innerHTML=`<span><i></i>CONCEPT 02 <b>Fictional ERP records · simulated analytical outputs</b></span><button data-action="nav-ERP data room">${recordCount()} synthetic records ${icon('arrow')}</button>`;if(state.role==='Buyer'){const views={'Control tower':controlTower,'Metrics & Forecasting':analyticsLab,'Fleet & maintenance':fleetPage,'ERP data room':dataRoom};if(views[state.view])$('main').innerHTML=views[state.view]()+`<footer><span>${icon(saved?'check':'warning')}${saved?'Scenario saved locally':'Storage unavailable; export before leaving'}</span><span>Fixed snapshot Nov 20, 2026 · synthetic data only · no live integration</span></footer>`}if(state.role==='Supplier')$('main footer').insertAdjacentHTML('beforebegin',supplierAirlineInbox());};
actions=function(){return lab.org==='Airline'?airlineActions():oldActions()};
demand=function(){return lab.org==='Airline'?fleetPage():oldDemand()};
marketplace=function(){return lab.org==='Airline'?airlineMarketplace():oldMarket()};
data=function(){return `<div class="lab-data-link">${simNote('ERP and analytical assumptions are inspectable in the Data Room and Metrics & Forecasting. Sharing controls are a workflow preview, not secure multi-company access.')}${btn('Open ERP data room','lab-nav-ERP data room','primary','file')}${btn('Inspect forecast method','lab-method','','spark')}</div>`+oldData()};
function recordCount(){return ['catalog','suppliers','history','inventory','orders','fleet','installed','jobs'].reduce((n,key)=>n+D[key].length,0)}
function lineChart(rows){const w=730,h=235,l=42,r=15,t=15,b=34,max=Math.ceil(Math.max(...rows.map(r=>Math.max(r.high,r.supply)))/50)*50||100,x=i=>l+i*(w-l-r)/(rows.length-1),y=n=>h-b-n/max*(h-t-b);const path=key=>rows.map((v,i)=>`${x(i)},${y(v[key])}`).join(' ');return `<svg viewBox="0 0 ${w} ${h}" class="forecast-chart" role="img" aria-label="Hypothetical monthly demand, assumed uncertainty range, and supplier output scenario"><defs><linearGradient id="lab-area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#d8e5dc" stop-opacity=".65"/><stop offset="1" stop-color="#eff5ee" stop-opacity=".3"/></linearGradient></defs>${[0,.25,.5,.75,1].map(k=>`<line x1="${l}" x2="${w-r}" y1="${y(max*k)}" y2="${y(max*k)}" stroke="#edf1eb"/><text x="${l-10}" y="${y(max*k)+3}" text-anchor="end">${Math.round(max*k)}</text>`).join('')}<polygon points="${path('high')} ${rows.map((v,i)=>`${x(i)},${y(v.low)}`).reverse().join(' ')}" fill="url(#lab-area)"/><polyline points="${path('supply')}" fill="none" stroke="#6f9a84" stroke-width="2.5"/><polyline points="${path('demand')}" fill="none" stroke="#23485a" stroke-width="2.5"/>${rows.map((v,i)=>i%Math.max(1,Math.floor(rows.length/5))===0||i===rows.length-1?`<text x="${x(i)}" y="${h-10}" text-anchor="middle">${v.label}</text>`:'').join('')}</svg>`}
function controlTower(){const oem=lab.org==='OEM',rows=A.oemRows(D,lab,state),jobs=A.airlineJobs(D,lab,state),risk=oem?rows.filter(r=>r.gap):jobs.filter(j=>j.gap),fRows=forecastRows(),late=fRows.filter(x=>x.f.date>x.f.row.promised),rem=A.reminders(D,lab).filter(r=>r.action),focus=oem?[...risk].sort((a,b)=>b.value-a.value)[0]:risk[0];return `${heading(oem?'OEM PRODUCTION INTELLIGENCE':'AIRLINE MAINTENANCE INTELLIGENCE',oem?'See the next constraint.<br><em>Act before the build.</em>':'See the next maintenance need.<br><em>Source before the wait.</em>',oem?'Link component demand, ERP commitments and supplier readiness across the next 12 weeks.':'Connect fleet work orders, component planning targets, usable stock and sourcing options.',btn('Run pitch scenario','lab-pitch','primary','arrow'))}${simNote()}<section class="intelligence-hero"><div><span class="eyebrow">${orgName().toUpperCase()} / ${oem?'PRODUCTION':'FLEET'} CONTROL TOWER</span><h2>${oem?'One delayed casting.<br>A whole plan exposed.':'One part missing.<br>A maintenance plan exposed.'}</h2><p>${oem?'Readiness signals reveal what the supplier promise alone leaves out.':'A work order needs the right part by its due date—not just a purchase order.'}</p></div><div class="hero-signal"><span>MODEL-BASED EXCEPTIONS</span><strong>${risk.length}</strong><p>${oem?'component lines with an uncovered need':'work orders with a modeled material gap'}</p>${btn('Inspect the analysis','lab-nav-Metrics & Forecasting','','arrow')}</div></section>${oem?labMetrics([['Component lines exposed',risk.length,rows.length+' modeled lines · 12 weeks'],['Uncovered part value',money(risk.reduce((s,r)=>s+r.value,0)),'Quantity gap × fictional unit price; not lost revenue'],['PO dates challenged',late.length,fRows.length+' open schedule lines · modeled median later than promise'],['Readiness checks',fRows.filter(x=>x.f.missing||x.f.stale).length,'Withheld or stale source signals']]):labMetrics([['Material-exposed work orders',risk.length,jobs.length+' planned work orders'],['Aircraft with exposed work',new Set(risk.map(j=>j.aircraft)).size,'Planning exposure; not a grounding determination'],['Reorder windows open',rem.length,'48 component planning records · next 30 days'],['Supplier dates challenged',late.length,'18 open airline PO schedule lines']])}<div class="intelligence-grid"><section class="panel"><div class="panel-head"><div><span class="eyebrow">${oem?'12–24 MONTH DEMAND / CAPACITY SCENARIO':'NEXT 8 WEEKS / MAINTENANCE MATERIAL COVERAGE'}</span><h2>${oem?'The future need meets the supply.':'Which work packages need attention?'}</h2></div>${oem?`<div class="mini-segment"><button data-action="lab-horizon-12" class="${horizon===12?'selected':''}">12m</button><button data-action="lab-horizon-24" class="${horizon===24?'selected':''}">24m</button></div>`:pill('Due-date allocation')}</div>${oem?`<div class="chart-legend"><span><i class="dash"></i>Housing demand</span><span><i></i>Assumed supplier output</span><span>Shading: assumed ±20% / ±35%</span></div>${lineChart(A.outlook(D,lab,state).slice(0,horizon))}<p class="chart-note">Hypothetical monthly trajectory, not a trained long-range forecast. Starts from quarterly housing requirements and known commitments; growth and uncertainty bands are explicit assumptions explained in the method.</p>`:maintenanceBars(jobs)}${btn('Change the assumptions','lab-nav-Metrics & Forecasting','small','sliders')}</section><section class="panel insight-brief"><div class="brief-heading">${icon('spark')}SCENARIO BRIEF</div><h2>${focus?oem?focus.part.name:focus.part.name:'No modeled gap in this scenario.'}</h2><p>${focus?oem?`${focus.gap.toLocaleString()} units uncovered by ${date(focus.due)}. Review raw material, usable inventory and the modeled receipt window before choosing a response.`:`${focus.id} · ${focus.aircraft} needs ${focus.qty} units by ${date(focus.due)}. ${focus.gap} remain uncovered after earlier jobs and eligible expected receipts.`:'Keep source timestamps and supplier commitments current.'}</p>${focus?btn(oem?'Explore sourcing & commitments':'Compare a response',oem?(state.parts.some(p=>p.id===focus.part.id)?'resolve-'+focus.part.id:'lab-line-'+D.orders.find(o=>o.org==='OEM'&&o.partId===focus.part.id).id):'lab-job-'+focus.id,'primary','arrow'):''}<div class="brief-foot">${icon('shield')}No automatic purchasing. People review assumptions and approve the response.</div></section></div><section class="panel table-panel"><div class="panel-head"><div><span class="eyebrow">TRACE THE SIGNAL TO ITS SOURCE</span><h2>${oem?'Material exceptions by component':'Maintenance jobs behind the exposure'}</h2><p>Every quantity and modeled arrival comes from inspectable fictional records.</p></div>${btn('Open data room','lab-nav-ERP data room','small','file')}</div>${oem?oemTable(rows):jobsTable(jobs.slice(0,8))}</section><div class="bottom-story"><div>${icon('link')}<h3>Demand → readiness → decision → supplier response</h3><p>${oem?'Production teams can act on supplier conditions while a purchasing decision still has time to matter.':'Maintenance teams can compare a replacement, an earlier purchase or an eligible service loaner without confusing loaners with manufacturing supply.'}</p></div>${btn('Walk through the demo','lab-pitch','','arrow')}</div>`}
function oemTable(rows){return `<div class="table-scroll"><table><thead><tr><th>Component</th><th>Forecast need</th><th>Usable now</th><th>Modeled supply by need date</th><th>Gap</th><th>Receipt estimate</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="part-link" data-action="lab-line-${r.forecast.row.id}">${r.part.name}</button><small>${r.part.code}</small></td><td>${r.demand.toLocaleString()}<small>${date(r.due)}</small></td><td>${r.stock.toLocaleString()}</td><td>${(r.incoming+r.newSupply).toLocaleString()}<small>Expected future supply, not on hand</small></td><td>${pill(r.gap?r.gap.toLocaleString()+' short':'Modeled covered',r.gap?'amber':'green')}</td><td>${date(r.forecast.date)}<small>${r.forecast.missing?'Shared readiness missing':r.forecast.stale?'Source stale':Math.round(r.forecast.probability*100)+'% assumed by supplier promise'}</small></td></tr>`).join('')}</tbody></table></div>`}
function maintenanceBars(jobs){const buckets=Array.from({length:8},(_,i)=>{const start=A.add(A.BASE,i*7),end=A.add(start,6),rows=jobs.filter(j=>j.due>=start&&j.due<=end);return {label:'W'+(i+1),count:rows.length,gap:rows.filter(j=>j.gap).length}}),max=Math.max(1,...buckets.map(b=>b.count));return `<div class="maintenance-chart">${buckets.map(b=>`<div><span>${b.count}</span><div class="maintenance-column"><i style="height:${b.count/max*145}px"><em style="height:${b.count?b.gap/b.count*100:0}%"></em></i></div><small>${b.label}</small></div>`).join('')}</div><div class="chart-legend"><span><i></i>Work orders modeled covered</span><span><i class="amber-line"></i>Material-exposed work orders</span></div><p class="chart-note">Quantities are allocated in due-date order, excluding held and reserved inventory. Expected receipts use modeled median dates. This is not maintenance release or dispatch authorization.</p>`}
function analyticsLab(){const before={...lab,uplift:0,delay:0,earlyMaterial:false,utilization:1},baseRows=lab.org==='OEM'?A.oemRows(D,before,state):A.airlineJobs(D,before,state),afterRows=lab.org==='OEM'?A.oemRows(D,lab,state):A.airlineJobs(D,lab,state),baseGap=baseRows.filter(x=>x.gap).length,afterGap=afterRows.filter(x=>x.gap).length,b=A.backtest(D),rows=forecastRows();return `${heading('METRICS & FORECASTING / FICTIONAL ERP HISTORY','Make the forecast<br><em>show its work.</em>','Change one assumption, inspect the effect and trace the prediction to its inputs.',btn('Forecast method','lab-method','','note'))}${simNote('The scenario estimator uses fictional receipt history and explicit readiness allowances. Outputs and calculated backtest results do not establish real-world performance.')}<div class="lab-layout"><section class="panel scenario-panel"><span class="eyebrow">WHAT IF?</span><h2>Stress-test the plan.</h2><form id="lab-scenario">${lab.org==='OEM'?`<label>Demand uplift <span id="lab-uplift-label">${lab.uplift}%</span><input type="range" name="uplift" aria-label="Demand uplift" min="0" max="40" step="5" value="${lab.uplift}"></label>`:`<input type="hidden" name="uplift" value="${lab.uplift}"><p class="fine-print">Work-order quantities come from the MRO schedule. Component utilization changes projected replacement targets, while delivery disruption changes expected material coverage.</p>`}<label>Delivery disruption<select name="delay" aria-label="Delivery disruption">${[0,7,14,30,60].map(n=>`<option value="${n}" ${lab.delay===n?'selected':''}>${n?'Add '+n+' calendar days':'No additional disruption'}</option>`).join('')}</select></label>${lab.org==='Airline'?`<label>Component utilization<select name="utilization" aria-label="Component utilization">${[1,1.1,1.25,1.4].map(n=>`<option value="${n}" ${lab.utilization===n?'selected':''}>${Math.round((n-1)*100)}% above baseline</option>`).join('')}</select></label>`:''}${lab.org==='OEM'?`<label class="check-label"><input name="earlyMaterial" type="checkbox" ${lab.earlyMaterial?'checked':''}><span>What if raw material was committed early?<small>Removes the 21-day material allowance from shared, affected records. It does not create real capacity or a purchase.</small></span></label>`:``}<button type="submit" class="btn primary">Recalculate scenario ${icon('refresh')}</button>${btn('Reset assumptions','lab-baseline','small')}</form><div class="scenario-delta"><span>Lines / jobs with a gap</span><strong>${baseGap} ${icon('arrow')} ${afterGap}</strong><small>Baseline → selected scenario. Same current records and accepted actions.</small>${lab.org==='OEM'?`<div class="value-delta"><span>Uncovered part value · baseline → scenario</span><strong>${money(baseRows.reduce((n,r)=>n+r.value,0))}<br>→ ${money(afterRows.reduce((n,r)=>n+r.value,0))}</strong><small>Quantity gap × fictional price. Not savings, revenue or loss.</small></div><small class="material-date">Forging median without early material: ${date(A.forecast(D,{...lab,earlyMaterial:false},D.orders.find(o=>o.org==='OEM'&&o.partId==='forging'),state).date)}<br>Selected scenario: ${date(A.forecast(D,lab,D.orders.find(o=>o.org==='OEM'&&o.partId==='forging'),state).date)}</small>`:`<small>Reorder windows open: ${A.reminders(D,lab).filter(r=>r.action).length}. Utilization affects these projected targets.</small>`}</div></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">${lab.org==='OEM'?'24-MONTH HOUSING OUTLOOK':'AIRLINE MATERIAL PLAN'}</span><h2>${lab.org==='OEM'?'Test an earlier material decision.':'See the work orders behind the gap.'}</h2></div>${lab.org==='OEM'?pill(lab.earlyMaterial?'Early-material scenario':'Current material assumptions',lab.earlyMaterial?'green':'amber'):pill('Scheduled maintenance scenario')}</div>${lab.org==='OEM'?`<div class="chart-legend"><span><i class="dash"></i>Demand scenario</span><span><i></i>Output scenario</span><span>Assumed uncertainty band</span></div>`:''}${lab.org==='OEM'?lineChart(A.outlook(D,lab,state)):maintenanceBars(A.airlineJobs(D,lab,state))}<p class="chart-note">${lab.org==='Airline'?'The airline chart allocates material against fixed work orders. Utilization changes component replacement reminders, not scheduled job quantities. The separate OEM long-range chart assumes':'The long-range chart assumes'} 1.2% monthly demand growth. Supply grows 0.6% monthly for 12 months; early material includes shared unallocated upside. Neither trajectory is a capacity guarantee. Bands are ±20% for months 1–12, ±35% for 13–24.</p><div class="method-ribbon"><span>Demand: editable forecast</span><span>Supply: dated commitments</span><span>Readiness: selected supplier data</span></div></section></div><section class="panel"><div class="panel-head"><div><span class="eyebrow">SYNTHETIC BACKTEST / NOT REAL ACCURACY</span><h2>Compare the estimator with simpler baselines.</h2><p>Computed from ${b.count} held-out fictional receipts. Each prediction uses only training receipts available by that order date.</p></div>${btn('Inspect scored records','lab-scored','small','file')}</div><div class="backtest-grid"><div class="error-bars">${[['Supplier promise',b.promiseMae,'#b9c4b9'],['Historical median',b.medianMae,'#9aafa7'],['Readiness estimator',b.mae,'#2d5866']].map(([n,v,c])=>`<div><span>${n}</span><div><i style="width:${v/Math.max(b.promiseMae,b.medianMae,b.mae)*100}%;background:${c}"></i></div><strong>${v.toFixed(1)} days</strong></div>`).join('')}<small>Mean absolute delivery-date error · lower is better</small></div><div class="interval-card"><span>Test rows inside modeled window</span><strong>${b.intervalCoverage.toFixed(0)}%</strong><p>Observed on synthetic holdout only. Windows use an empirical training-error allowance with a 7-day minimum; no real-world confidence level is claimed.</p></div></div><div class="backtest-caution">The fictional generator contains built-in relationships between readiness and delay. Strong results on these examples do not prove that the same method works on real suppliers.</div></section><section class="panel table-panel"><div class="panel-head"><div><span class="eyebrow">OPEN PURCHASE ORDER ANALYSIS</span><h2>Supplier promises, with context.</h2></div>${pill(lab.org+' records only')}</div>${forecastTable(rows)}</section>`}
function forecastTable(rows){return `<div class="table-scroll"><table><thead><tr><th>PO / component</th><th>Open quantity</th><th>Supplier promise</th><th>Modeled receipt window</th><th>Assumed on-time likelihood</th><th></th></tr></thead><tbody>${rows.map(({o,f})=>`<tr><td>${o.id}<small>${D.catalog.find(p=>p.id===o.partId).name}</small></td><td>${o.qty-o.receivedQty}</td><td>${date(f.row.promised)}</td><td>${date(f.early)} – ${date(f.late)}<small>Median ${date(f.date)}</small></td><td>${pill(Math.round(f.probability*100)+'%',f.probability<.5?'amber':'green')}<small>${f.missing?'Readiness withheld':f.stale?'Stale signal':'Uncalibrated · synthetic'}</small></td><td>${btn('Why?',`lab-line-${o.id}`,'small','arrow')}</td></tr>`).join('')}</tbody></table></div>`}
function lineDetail(id){const o=D.orders.find(o=>o.id===id);if(!o)return;const f=A.forecast(D,lab,o,state),part=D.catalog.find(p=>p.id===o.partId);open('Inside the estimate · '+o.id,`<div class="part-detail-head">${photo(part.art)}<div><span class="code">${part.code}</span><h3>${part.name}</h3><p>${D.suppliers.find(s=>s.id===o.supplier).name} · ${o.org} ERP schedule line ${o.scheduleLine}</p>${pill('All inputs fictional')}</div></div><div class="detail-facts"><div><span>Supplier promise</span><strong>${date(f.row.promised)}</strong></div><div><span>Modeled median</span><strong>${date(f.date)}</strong></div><div><span>Assumed window</span><strong>${date(f.early)} – ${date(f.late)}</strong></div><div><span>By promise date</span><strong>${Math.round(f.probability*100)}%<small>Uncalibrated synthetic likelihood</small></strong></div></div><h3>From the ERP line to the delivery estimate</h3><div class="drivers"><div><span>Order date</span><strong>${date(o.ordered)}</strong></div><div><span>Historical unconstrained baseline · ${f.sample} prior receipts</span><strong>${f.baseline.toFixed(1)} days</strong></div>${f.drivers.filter(x=>x.days).map(x=>`<div><span>${x.label}</span><strong>+${x.days.toFixed(1)} days</strong></div>`).join('')}<div><span>Selected disruption scenario</span><strong>+${lab.delay} days</strong></div><div><span>Total modeled lead time</span><strong>${f.lead} days</strong></div></div>${f.stale||f.missing?`<div class="inline-notice amber">${icon('warning')}<p>${f.missing?'Supplier readiness is withheld. Raw hidden fields are excluded; the estimator falls back to historical lead behavior and widens its window.':''} ${f.stale?'Source update is older than 48 hours relative to the snapshot. The window is widened.':''}</p></div>`:''}<p class="fine-print">Open quantity ${o.qty-o.receivedQty}; fictional part value ${money((o.qty-o.receivedQty)*part.price)}. New commitments are expected receipts, never on-hand inventory. This estimate is not a supplier quote or delivery guarantee.</p><div class="dialog-actions">${state.parts.some(p=>p.id===part.id)&&o.org==='OEM'?btn('Compare stock & commitments','resolve-'+part.id,'primary','arrow'):btn('Inspect source records','lab-nav-ERP data room','primary','file')}${btn('Change scenario','lab-nav-Metrics & Forecasting','','sliders')}</div>`)}
function jobsTable(rows){return `<div class="table-scroll"><table><thead><tr><th>Work order / aircraft</th><th>Component / due</th><th>Need</th><th>Usable stock pool</th><th>Material status</th><th></th></tr></thead><tbody>${rows.map(j=>`<tr><td>${j.id}<small>${j.aircraft} · ${j.type} · ${j.base}</small></td><td>${j.part.name}<small>${date(j.due)}</small></td><td>${j.qty}</td><td>${j.inv.usable}<small>Before allocation to earlier work</small></td><td>${pill(j.gap?j.gap+' units uncovered':'Modeled covered',j.gap?'amber':'green')}<small>${j.dedicated?'Includes accepted dedicated response':'Median-date receipts assumed'}</small></td><td>${btn('Review',`lab-job-${j.id}`,'small','arrow')}</td></tr>`).join('')}</tbody></table></div>`}
function fleetPage(){const jobs=A.airlineJobs(D,lab,state),rem=A.reminders(D,lab);return `${heading('AIRLINE / FLEET & MAINTENANCE','Plan the next removal.<br><em>Protect the next schedule.</em>','Fictional maintenance work, installed-component records and procurement reminders for Westhaven Air.',btn('Airline control tower','lab-airline-home','','arrow'))}${simNote('These dates are planning targets and synthetic utilization projections—not manufacturer life limits, maintenance instructions, dispatch decisions or airworthiness approvals.')}<div class="page-tabs">${[['jobs','Work orders · 36'],['reminders','Replacement planning · 48'],['fleet','Aircraft · 16']].map(([id,label])=>`<button data-action="lab-fleet-${id}" class="${fleetTab===id?'selected':''}">${label}</button>`).join('')}</div><section class="panel table-panel"><div class="panel-head"><div><h2>${fleetTab==='jobs'?'The job-level material plan':fleetTab==='reminders'?'Reorder before the projected need':'The sample operating fleet'}</h2><p>${fleetTab==='jobs'?'Prior work consumes availability first; held and reserved stock never covers a job.':fleetTab==='reminders'?'Earliest calendar/hour/cycle target, minus procurement lead time and advance buffer.':'Aircraft IDs are fictional—not actual registrations. Component eligibility is not established.'}</p></div></div>${fleetTab==='jobs'?jobsTable(jobs):fleetTab==='reminders'?`<div class="table-scroll"><table><thead><tr><th>Component / aircraft</th><th>Installed / serial</th><th>Projected planning target</th><th>Reorder by</th><th></th></tr></thead><tbody>${rem.map(r=>`<tr><td>${r.part.name}<small>${r.aircraft}</small></td><td>${date(r.installed)}<small>${r.serial}</small></td><td>${date(r.target)}<small>${r.reason}</small></td><td>${pill(date(r.reorder),r.action?'amber':'green')}<small>${r.part.lead}d procurement + ${lab.buffer}d buffer</small></td><td>${btn('Edit targets','lab-component-'+r.id,'small','sliders')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="table-scroll"><table><thead><tr><th>Demo aircraft</th><th>Type / base</th><th>Total flight hours</th><th>Total cycles</th><th>Daily usage assumption</th></tr></thead><tbody>${D.fleet.map(a=>`<tr><td>${a.id}</td><td>${a.type}<small>${a.base}</small></td><td>${a.hours.toLocaleString()}</td><td>${a.cycles.toLocaleString()}</td><td>${a.hoursPerDay} h / ${a.cyclesPerDay} cycles<small>Separate from component-specific APU usage</small></td></tr>`).join('')}</tbody></table></div>`}</section>`}
function jobDetail(id){const j=A.airlineJobs(D,lab,state).find(j=>j.id===id);if(!j)return;const bridgeDate=j.forecast?.date||A.add(A.BASE,j.part.lead),days=Math.max(1,A.days(bridgeDate,A.BASE)),rent=days*1200+1100;open('Maintenance response · '+j.id,`<div class="part-detail-head">${photo(j.part.art)}<div><span class="code">${j.part.code}</span><h3>${j.part.name} · ${j.aircraft}</h3><p>${j.task} · ${j.qty} units by ${date(j.due)} · ${j.gap} uncovered</p>${pill(j.gap?'Material response needed':'Modeled covered',j.gap?'amber':'green')}</div></div><div class="detail-facts"><div><span>Stock on hand</span><strong>${j.inv.onHand}</strong></div><div><span>Held / reserved</span><strong>${j.inv.held+j.inv.reserved}</strong></div><div><span>Usable before prior jobs</span><strong>${j.inv.usable}</strong></div><div><span>Modeled PO receipt</span><strong>${j.forecast?date(j.forecast.date):'None'}</strong></div></div><p class="fine-print">This work order’s gap reflects earlier due-date allocations, not just the warehouse total. Accepted responses apply only to this work order and never add OEM manufacturing supply.</p><div class="response-options"><section><span class="eyebrow">PURCHASE SCENARIO</span><h3>Source a replacement</h3><strong>${money(j.part.price)} / unit</strong><p>Assumed sourcing lead: ${j.part.lead} days · arrives ${date(A.add(A.BASE,j.part.lead))}</p>${btn('Request a purchase','lab-air-request-Purchase-'+j.id,'primary','arrow')}</section>${j.partId==='apu'?`<section><span class="eyebrow">SEPARATE SERVICE LOANER POOL</span><h3>Bridge the replacement wait</h3><strong>$1,200 / day</strong><p>Loaner arrival: 2 days. ${days} billed days: ${money(rent)} expense + $15,000 refundable deposit. Initial cash: ${money(rent+15000)}.</p>${btn('Request a loaner','lab-air-request-Loaner-'+j.id,'primary','arrow')}</section>`:`<section><span class="eyebrow">REVIEW THE EXISTING ORDER</span><h3>Understand the timing risk</h3><p>Compare the supplier promise with readiness and historical lead behavior before choosing an expedited response.</p>${j.forecast?btn('Inspect PO estimate','lab-line-'+j.forecast.row.id,'','note'):''}</section>`}</div><p class="fine-print">All prices are invented. Bridge uses the existing PO’s modeled receipt ${date(bridgeDate)}, loaner arrival day 2 and two return days; ${days} billed days. A newly purchased replacement is a separate ${j.part.lead}-day option. Taxes, damage, added days and downtime cost excluded. Fit, documentation and operator approval require authorized review. No serviceability or airworthiness determination is made.</p>`)}
function airlineRequest(kind,id){const job=D.jobs.find(j=>j.id===id),part=D.catalog.find(p=>p.id===job.partId),order=D.orders.find(o=>o.org==='Airline'&&o.partId===part.id),bridgeDays=order?Math.max(1,A.days(A.forecast(D,lab,order,state).date,A.BASE)):part.lead;open('Create airline '+kind.toLowerCase()+' request',`<h3>${part.name} · ${id}</h3><form id="air-request" data-job="${id}" data-kind="${kind}"><div class="form-grid"><label>Quantity<input name="qty" type="number" min="1" max="${job.qty}" step="1" value="1" required></label><label>Responsible planner<input name="owner" value="${esc(job.owner)}" maxlength="80" required></label>${kind==='Loaner'?`<label>Expected billed rental days<input name="days" type="number" value="${bridgeDays}" min="1" max="365" step="1" required></label><div class="quote-total"><span>Estimated expense</span><strong id="air-rental-expense">${money(bridgeDays*1200+1100)}</strong><small>Per unit, plus $15,000 refundable deposit. $1,200/day + $500 fees + $600 shipping.</small></div>`:''}</div><label class="check-label"><input type="checkbox" required><span>This is a synthetic sourcing request. Qualification and documentation still need review. No order, rental or payment is sent.</span></label><p class="fine-print">Buyer approval and a separate supplier acceptance are required. The two-unit demo loaner pool stays separate from warehouse stock and OEM capacity.</p><button class="btn primary" type="submit">Create review request ${icon('arrow')}</button></form>`)}
function airlineActions(){return `${heading('AIRLINE DECISIONS / WESTHAVEN AIR','Keep the work order<br>and the response <em>together.</em>','Review a sourcing request, then have the simulated supplier accept its date and quantity.',btn('Review work orders','lab-nav-Fleet & maintenance','','plane'))}${simNote()}<div class="action-list">${lab.actions.length?lab.actions.slice().reverse().map(a=>`<section class="panel action-card"><div class="action-top"><span class="code">${a.id} · ${a.kind}</span>${pill(a.status,a.status==='Confirmed'?'green':'amber')}</div><h3>${D.catalog.find(p=>p.id===a.partId).name} · ${a.qty} units</h3><p>${a.jobId} · Owner ${esc(a.owner)}</p><div class="action-meta"><span>Proposed / accepted receipt<strong>${date(a.eta)}</strong></span><span>Expense assumption<strong>${money(a.expense)}</strong></span><span>Refundable deposit<strong>${money(a.deposit)}</strong></span></div>${a.status==='Buyer review'?btn('Review request','lab-air-review-'+a.id,'primary','check'):a.status==='Awaiting supplier'?btn('Open supplier response','lab-air-supplier-'+a.id,'primary','users'):''}${btn('View work order','lab-job-'+a.jobId,'small','arrow')}</section>`).join(''):`<section class="panel empty"><h3>No airline requests yet.</h3><p>Review a work order to compare a purchase or service APU loaner.</p>${btn('Open work orders','lab-nav-Fleet & maintenance','primary','arrow')}</section>`}</div>`}
function supplierAirlineInbox(){const requests=lab.actions.filter(a=>a.status==='Awaiting supplier'&&a.supplier===state.supplier);return `<section class="panel airline-inbox"><div class="panel-head"><div><span class="eyebrow">SEPARATE CUSTOMER / WESTHAVEN AIR</span><h2>${requests.length} airline requests awaiting acceptance</h2><p>Only the request quantity, part and due-date context is shared here.</p></div></div>${requests.map(a=>`<div class="supplier-request"><div><span class="code">${a.id} · ${a.jobId}</span><h3>${a.kind} · ${D.catalog.find(p=>p.id===a.partId).name} · ${a.qty} units</h3><p>Proposed ${date(a.eta)}</p></div>${btn('Respond','lab-air-respond-'+a.id,'primary','arrow')}</div>`).join('')||'<p class="muted">No airline requests for this supplier in the scenario.</p>'}</section>`}
function airlineMarketplace(){const parts=D.catalog.filter(p=>D.jobs.some(j=>j.partId===p.id)).filter(p=>[p.name,p.code].join(' ').toLowerCase().includes(search.toLowerCase()));return `${heading('AIRLINE SOURCING SCENARIOS','Plan the replacement.<br><em>Compare the bridge.</em>','Fictional sourcing estimates for the parts in Westhaven Air’s work orders.')}${simNote('These are replacement sourcing scenarios—not live offers or supplier quotes. Inventory belonging to the airline is not being advertised for sale.')}<div class="offer-grid airline-market">${parts.map(p=>{const job=A.airlineJobs(D,lab,state).find(j=>j.partId===p.id&&j.gap)||D.jobs.find(j=>j.partId===p.id);return `<article class="offer-card"><div class="offer-image">${photo(p.art)}<span class="condition">Sourcing scenario</span></div><div class="offer-body"><span class="code">${p.code}</span><h3>${p.name}</h3><p>${D.suppliers.find(s=>s.id===p.supplier).name} · fictional</p><div class="stock-line"><span>Assumed replacement lead</span><strong>${p.lead} days</strong></div><div class="offer-price"><strong>${money(p.price)}</strong><span>Invented unit price</span></div><p class="trace-note">${icon('file')}Configuration and traceability review required</p>${btn(p.id==='apu'?'Compare purchase / loaner':'Review work-order need','lab-job-'+job.id,'primary','arrow')}</div></article>`}).join('')}</div>`}
function componentEditor(id){const r=A.reminders(D,lab).find(r=>r.id===id);open('Edit component planning targets',`<span class="code">${r.id} · ${r.serial}</span><h3>${r.part.name} · ${r.aircraft}</h3><form id="lab-component" data-id="${id}"><div class="form-grid">${[['calendarDays','Calendar target · days',1],['limitHours','Hours planning target',1],['limitCycles','Cycles planning target',1],['usedHours','Hours accumulated',0],['usedCycles','Cycles accumulated',0],['hoursPerDay','Component hours per day',.1],['cyclesPerDay','Component cycles per day',.1]].map(([key,label,min])=>`<label>${label}<input type="number" name="${key}" value="${r[key]}" min="${min}" max="1000000" step="${key.includes('PerDay')?'.1':'1'}" required></label>`).join('')}</div><p class="fine-print">Installed ${date(r.installed)}. These are invented planning assumptions—not approved maintenance limits. Earliest calendar/hour/cycle target drives the date. A Monitor condition advances the target by 7 days; procurement lead and the advance buffer move the reorder date earlier.</p><button class="btn primary" type="submit">Save planning assumptions ${icon('check')}</button></form>`)}
const inventoryHeaders=['organization','part_id','on_hand','reserved','held','updated_date'];
function csvText(rows,headers){return [headers.join(','),...rows.map(r=>headers.map(h=>'"'+String(r[h]??'').replace(/"/g,'""')+'"').join(','))].join('\r\n')}
function labDownload(name,text,type='text/csv'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function inventoryCSV(){return D.inventory.map(r=>{const row={...r,...lab.inventoryOverrides[r.id]};return {organization:row.org,part_id:row.partId,on_hand:row.onHand,reserved:row.reserved,held:row.held,updated_date:row.updated}})}
function readCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell.trim());cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell.trim());if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('Unclosed CSV quotation.');row.push(cell.trim());if(row.some(Boolean))rows.push(row);const headers=rows.shift();if(!headers||headers.length!==inventoryHeaders.length||inventoryHeaders.some(h=>!headers.includes(h)))throw Error('Use the exact sample inventory headers.');if(rows.length>1000)throw Error('Limit this demo import to 1,000 rows.');return rows.map((r,i)=>{if(r.length!==headers.length)throw Error('Row '+(i+2)+' has the wrong number of fields.');return Object.fromEntries(headers.map((h,j)=>[h,r[j]]))})}
function roomRecords(){const org=lab.org;switch(labTab){case'orders':return D.orders.filter(r=>r.org===org).map(r=>{const f=A.forecast(D,lab,r,state);return {id:r.id,part:D.catalog.find(p=>p.id===r.partId).code,quantity:r.qty,received:r.receivedQty,requested:r.requested,promised:f.row.promised,modeled:f.date,status:r.status}});case'history':return D.history.map(r=>({id:r.id,part:D.catalog.find(p=>p.id===r.partId)?.code||r.partId,ordered:r.ordered,promised:r.promised,received:r.received,quantity:r.qty,split:r.split}));case'inventory':return D.inventory.filter(r=>r.org===org).map(r=>{const x=A.inventory(D,lab,org,r.partId);return {id:r.id,part:D.catalog.find(p=>p.id===r.partId)?.code||r.partId,on_hand:x.onHand,reserved:x.reserved,held:x.held,usable:x.usable,warehouse:r.warehouse,updated:x.updated}});case'fleet':return D.fleet.map(r=>({aircraft:r.id,type:r.type,base:r.base,hours:r.hours,cycles:r.cycles}));case'installed':return A.reminders(D,lab).map(r=>({id:r.id,aircraft:r.aircraft,part:D.catalog.find(p=>p.id===r.partId)?.code||r.partId,serial:r.serial,installed:r.installed,target:r.target,reorder:r.reorder}));case'jobs':return A.airlineJobs(D,lab,state).map(j=>({id:j.id,aircraft:j.aircraft,part:D.catalog.find(p=>p.id===j.partId)?.code||j.partId,quantity:j.qty,due:j.due,covered:j.covered,gap:j.gap}));case'catalog':return D.catalog.map(p=>({part:p.code,name:p.name,category:p.category,supplier:p.supplier,assumed_lead:p.lead,fictional_price:p.price}));default:return []}}
function dataRoom(){const all=roomRecords(),filtered=all.filter(r=>(typeof productText==='function'?productText(Object.values(r).join(' ')):Object.values(r).join(' ')).toLowerCase().includes(labQuery.toLowerCase())),pages=Math.max(1,Math.ceil(filtered.length/20));labPage=Math.min(labPage,pages);const rows=filtered.slice((labPage-1)*20,labPage*20),headers=Object.keys(all[0]||{});return `${heading('ERP DATA ROOM / TRACEABLE FICTION','Open the records.<br><em>Follow the evidence.</em>','A realistic record structure, with invented values and visible provenance.',btn('Export full demo package','lab-export','primary','download'))}${simNote('No SAP, Oracle, airline or OEM account is connected. The public references below inform field structure and component categories; they do not supply these quantities, prices or forecasts.')}<div class="three-columns connections"><section class="panel"><span class="connection-dot"></span><h3>ERP snapshot</h3><p>36 inventory records · 36 open PO lines · 360 past receipts</p>${pill('LOCAL SIMULATION')}${btn('Preview a simulated sync','lab-sync','small','refresh')}</section>${lab.org==='Airline'?`<section class="panel"><span class="connection-dot"></span><h3>Maintenance records</h3><p>16 aircraft · 48 installed components · 36 work orders</p>${pill('LOCAL SIMULATION')}${btn('View maintenance plan','lab-nav-Fleet & maintenance','small','plane')}</section>`:''}<section class="panel"><span class="connection-dot"></span><h3>Supplier readiness</h3><p>Material, tooling, capacity, yield and sharing controls</p>${pill('MANUAL DEMO INPUTS')}${btn('Open supplier workspace','role-Supplier','small','users')}</section></div><section class="panel table-panel"><div class="panel-head"><div><span class="eyebrow">${recordCount()} FICTIONAL RECORDS / SNAPSHOT NOV 20, 2026</span><h2>Inspect the source data</h2><p>ERP tables follow the selected organization. Aircraft and maintenance tables belong to Westhaven Air. Historical rows are a fictional shared training sample.</p></div><form id="lab-room-search"><input name="query" aria-label="Search data records" placeholder="Search record ID, part or date" value="${esc(labQuery)}"><button class="btn small" type="submit">Search</button></form></div><div class="page-tabs data-tabs">${[['orders','Open POs'],['history','Receipt history'],['inventory','Inventory'],...(lab.org==='Airline'?[['fleet','Aircraft'],['installed','Installed parts'],['jobs','Work orders']]:[]),['catalog','Part catalog']].map(([key,label])=>`<button data-action="lab-room-${key}" class="${labTab===key?'selected':''}">${label}</button>`).join('')}</div><div class="table-scroll"><table class="records-table"><thead><tr>${headers.map(h=>`<th>${h.replaceAll('_',' ')}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${headers.map(h=>`<td>${esc(r[h])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${!rows.length?'<div class="empty">No records match this search.</div>':''}<div class="record-pagination"><span>${filtered.length} records · page ${labPage} of ${pages}</span><div>${btn('Previous','lab-page-prev','small')}${btn('Next','lab-page-next','small')}${btn('Download this table','lab-table-export','small','download')}</div></div></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">TRY A BROWSER-LOCAL ERP HANDOFF</span><h2>Import an inventory snapshot.</h2><p>Download the exact schema, edit synthetic values, choose the file and review before applying. Nothing is uploaded.</p></div></div><div class="dialog-actions">${btn('Download sample CSV','lab-inventory-sample','','download')}<label class="btn primary file-button">${icon('file')}Choose inventory CSV<input id="lab-inventory-file" type="file" accept=".csv,text/csv"></label><a class="btn" href="assets/synthetic-erp.json" download>Download entire fictional dataset ${icon('download')}</a></div><p class="fine-print">Headers: ${inventoryHeaders.join(', ')}. Only known organization/part pairs; held + reserved cannot exceed on-hand. No future snapshot dates, duplicates or negative quantities. Import changes baseline inventory only; do not include new scenario purchases a second time.</p>${inventoryPreview?`<div class="import-preview"><h3>${inventoryPreview.errors.length?'Correct these rows':'Review '+Object.keys(inventoryPreview.patches).length+' inventory changes'}</h3>${inventoryPreview.errors.length?`<ul>${inventoryPreview.errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul>`:`<div class="table-scroll"><table><thead><tr><th>Record</th><th>On-hand</th><th>Reserved</th><th>Held</th><th>Usable</th></tr></thead><tbody>${Object.entries(inventoryPreview.patches).map(([id,r])=>`<tr><td>${id}</td><td>${r.onHand}</td><td>${r.reserved}</td><td>${r.held}</td><td>${r.onHand-r.reserved-r.held}</td></tr>`).join('')}</tbody></table></div>${btn('Apply reviewed inventory','lab-inventory-apply','primary','check')}`}</div>`:''}</section><section class="panel prose"><span class="eyebrow">PUBLIC REFERENCES / STRUCTURE, NOT DATA VALUES</span><h2>Recognizable records. Explicitly fictional numbers.</h2><p>SAP documentation describes purchase-order schedule dates and quantities, supplier confirmation dates and quantities, and goods-receipt processing. Those concepts inform the PO, promise and receipt fields used here.</p><p>Honeywell’s public APU information provides context for the 131-series and airline use cases. No DEMO part number is a real Honeywell part, and no aircraft/component compatibility is established by this prototype. Aircraft types are context labels only.</p><p>IATA describes persistent supply, maintenance and materials constraints. The scenario themes also reflect the team’s discovery discussions: material purchased late, tooling, supplier capacity, rework, longer-term demand and selective data sharing. No private company operating figures are published here.</p><div class="reference-links"><a href="https://help.sap.com/docs/SAP_S4HANA_ON-PREMISE/8308e6d301d54584a33cd04a9861bc52/6e52f71dfb5a481b810ce0697708baf2.html" target="_blank" rel="noopener">SAP · PO schedule-line fields ${icon('external')}</a><a href="https://help.sap.com/docs/SAP_S4HANA_ON-PREMISE/9905622a5c1f49ba84e9076fc83a9c2c/e69ac7536e8e2a4be10000000a174cb4.html" target="_blank" rel="noopener">SAP · goods receipts ${icon('external')}</a><a href="https://www.honeywellaerospace.com/us/en/products-and-services/products/power-and-propulsion/auxiliary-power-units" target="_blank" rel="noopener">Honeywell · APU context ${icon('external')}</a><a href="https://www.iata.org/en/programs/ops-infra/techops/aviation-supply-chain/" target="_blank" rel="noopener">IATA · supply-chain context ${icon('external')}</a></div><p class="fine-print">All organizations, people, prices, inventory, demand, readiness signals, serial numbers, limits and transactions are invented. No partnership, certification or actual inventory is claimed. Local role switching is not secure authentication.</p></section><div class="reset-zone"><div><strong>Reset the analytics demonstration.</strong><p>Resets analytical assumptions, inventory imports and airline requests. OEM network commitments remain separate.</p></div>${btn('Reset analytics','lab-reset-start','','refresh')}</div>`}
function methodDialog(){open('Forecast method & limits',`<div class="prose"><h3>Transparent estimator, not a trained AI service</h3><p>Each component has 15 fictional training receipts and five holdout receipts. For a live snapshot estimate, the baseline is the median of completed training lead times after subtracting explicit readiness allowances. Current shared inputs add material, tooling, utilization, yield and the selected delay scenario.</p><p>Material unconfirmed: +21 days. Tooling unready: +12 days. Above 80% utilization: +0.5 days per point. Yield below 94%: +10 days. These are invented demonstration assumptions, not industry-standard coefficients.</p><p>For a backtest prediction, only training receipts received by that test order’s date are available. The actual test receipt never influences its own estimate. This avoids a simple form of look-ahead leakage, but the entire dataset is artificial and the generator builds in relationships.</p><p>Windows use the 80th percentile of absolute training residuals with a seven-day minimum. Missing shared readiness adds 14 days; stale inputs add seven. The on-time score is a smoothed empirical share of training residuals that would meet the supplier promise. It is uncalibrated; no real-world probability or confidence guarantee is implied.</p><p>OEM material coverage is calculated at modeled median receipt dates. Network commitments show agreed dates separately. An accepted reservation is not counted as parts until converted to an approved and supplier-accepted production order. Airline stock is allocated in due-date order; held/reserved inventory is excluded.</p><p>Long-range demand and capacity charts are explicitly assumed trajectories, not a model trained on real production demand. Real validation would require permissioned timestamped data, chronological evaluation and comparison against current planning decisions.</p></div>`)}
function pitchDialog(){open('A judge-ready walkthrough',`<ol class="demo-steps"><li><strong>Start with a recognizable record.</strong> Open the ERP Data Room. Inspect a purchase order, its requested date, supplier promise, quantity and warehouse stock.</li><li><strong>Show why the promise needs context.</strong> Open Metrics & Forecasting → Why? for a casting or forging. Trace material, tooling and capacity allowances into the receipt estimate.</li><li><strong>Change the plan.</strong> Run the OEM stress scenario: +20% demand and a 30-day disruption. Compare the baseline with the changed outcome.</li><li><strong>Test a response.</strong> Enable early raw-material commitment. It changes the hypothetical estimate; it does not create stock or guarantee production. Use sourcing and supplier acceptance for an explicit decision record.</li><li><strong>Switch customers.</strong> Open Westhaven Air. Review an exposed APU work order, compare buying with a service loaner, then follow buyer review and supplier acceptance.</li></ol><div class="inline-notice">${icon('shield')}<p>Tell judges the records and outputs are fictional. The demonstration shows a proposed decision workflow, not unique industry capability, proven prediction accuracy or a connected company system.</p></div><div class="dialog-actions">${btn('Run OEM stress scenario','lab-demo-oem','primary','chart')}${btn('Show airline maintenance','lab-airline-home','','plane')}${btn('Inspect ERP records','lab-nav-ERP data room','','file')}</div>`)}
function airlineReview(id){const a=lab.actions.find(a=>a.id===id);if(!a||a.status!=='Buyer review')return;const j=D.jobs.find(j=>j.id===a.jobId);open('Airline buyer review · '+id,`<h3>${a.kind} · ${D.catalog.find(p=>p.id===a.partId).name} · ${a.qty} units</h3><div class="detail-facts"><div><span>Proposed receipt</span><strong>${date(a.eta)}</strong></div><div><span>Work-order need</span><strong>${date(j.due)}</strong></div><div><span>Expense assumption</span><strong>${money(a.expense)}</strong></div><div><span>Refundable deposit</span><strong>${money(a.deposit)}</strong></div></div>${a.eta>j.due?'<div class="inline-notice amber">The proposed receipt is after the work-order due date and will not close its current gap.</div>':''}<p class="fine-print">No payment, binding rental, part approval or real message is sent. Buyer approval alone does not change material coverage. A separate simulated supplier acceptance is required.</p><div class="dialog-actions">${btn('Reject request','lab-air-reject-'+id)}${btn('Approve scenario request','lab-air-approve-'+id,'primary','check')}</div>`)}
function airlineRespond(id){const a=lab.actions.find(a=>a.id===id);if(!a||a.status!=='Awaiting supplier'||state.role!=='Supplier'||state.supplier!==a.supplier)return;open('Airline supplier response · '+id,`<h3>${a.kind} · ${D.catalog.find(p=>p.id===a.partId).name} · ${a.qty} units</h3><p>${esc(M.suppliers[a.supplier]||a.supplier)} → Westhaven Air · ${a.jobId}</p><form id="air-response" data-id="${id}"><label>Accepted delivery date<input name="eta" type="date" value="${a.eta}" min="${A.BASE}" required></label><label class="check-label"><input name="ack" type="checkbox" required><span>For this fictional scenario, availability and the required configuration/document review have been resolved. This records expected service coverage only, not a real rental, transaction or airworthiness determination.</span></label><div class="dialog-actions">${btn('Decline request','lab-air-decline-'+id)}<button class="btn primary" type="submit">Accept in scenario ${icon('check')}</button></div></form>`)}
function syncPreview(){const inv=D.inventory.find(r=>r.org===lab.org&&r.partId===(lab.org==='OEM'?'housing':'apu')),current=A.inventory(D,lab,lab.org,inv.partId),o=D.orders.find(r=>r.org===lab.org&&r.partId===inv.partId),f=A.forecast(D,lab,o,state),newOnHand=Math.max(current.reserved+current.held,current.onHand-1);open('Preview a simulated ERP update',`<p>This stages a fictional warehouse count and supplier promise revision for ${orgName()}. Nothing is fetched from an ERP.</p><div class="drivers"><div><span>${inv.id} · on-hand units</span><strong>${current.onHand} → ${newOnHand}</strong></div><div><span>${o.id} · supplier promise</span><strong>${date(f.row.promised)} → ${date(A.add(f.row.promised,7))}</strong></div></div><p class="fine-print">The inventory update changes usable stock. Revising the promise changes the assumed on-time score; it does not by itself improve the underlying delivery estimate. Fixed scenario snapshot: ${date(A.BASE)}.</p><div class="dialog-actions">${btn('Cancel','close')}${btn('Apply staged local update','lab-sync-apply','primary','refresh')}</div>`)}
function applyInventory(patches){Object.assign(lab.inventoryOverrides,patches);for(const [id,fields]of Object.entries(patches)){const inv=D.inventory.find(x=>x.id===id),n=state.parts.find(p=>p.id===inv.partId);if(inv.org==='OEM'&&n)n.stock=fields.onHand-fields.reserved-fields.held}labSave();save()}
function ensureNetworkCatalog(){for(const s of D.suppliers)M.suppliers[s.id]=s.name;for(const part of D.catalog.filter(p=>p.quarterly)){const inv=A.inventory(D,lab,'OEM',part.id),o=D.orders.find(o=>o.org==='OEM'&&o.partId===part.id);if(!state.parts.some(p=>p.id===part.id)){state.parts.push({id:part.id,code:part.code,name:part.name,art:part.art,demand:part.quarterly,stock:inv.usable,committed:o.qty,commitDate:o.promised,due:A.add(A.BASE,84),supplier:part.supplier,share:true});state.capacity.push({id:'c_'+part.id,partId:part.id,supplier:part.supplier,additional:Math.max(10,Math.round(part.quarterly*.15)),ready:A.add(A.BASE,55),material:o.material,tooling:o.tooling,yield:o.yield,share:true,updated:o.updated,price:part.price*.88,fee:Math.round(part.price*2),condition:'Additional output requires material, tooling, configuration review and a separately accepted purchasing commitment.'});state.offers.push({id:'o_'+part.id,partId:part.id,supplier:part.supplier,name:M.suppliers[part.supplier],qty:Math.max(2,Math.round(part.quarterly*.08)),price:part.price,days:6,location:D.suppliers.find(s=>s.id===part.supplier).location,channel:'Independent shop',condition:'New'})}if(lab.inventoryOverrides[D.inventory.find(r=>r.org==='OEM'&&r.partId===part.id).id])state.parts.find(p=>p.id===part.id).stock=inv.usable}}
const renderAnalytics=render;
render=function(){ensureNetworkCatalog();if(state.role==='Buyer'&&((lab.org==='OEM'&&state.view==='Fleet & maintenance')||(lab.org==='Airline'&&state.view==='Demand & commitments')))state.view='Control tower';if(lab.org==='OEM'&&['fleet','installed','jobs'].includes(labTab))labTab='orders';renderAnalytics();const count=lab.org==='Airline'?lab.actions.filter(a=>a.status==='Buyer review').length:state.actions.filter(a=>a.status==='Buyer review').length;const badge=$('.request-cart span');if(badge)badge.textContent=count;if(lab.org==='Airline'){const item=$('.nav-item[data-action="nav-Actions"]');if(item)item.innerHTML=icon('note')+'<span>Actions</span>'+(count?'<em>'+count+'</em>':'')}const foot=$('main footer span:last-child');if(foot)foot.textContent='Fixed snapshot Nov 20, 2026 · fictional organizations · no live integrations'};
guide=pitchDialog;
supplierWorkspace=function(){return oldSupplier().replace('BUYER-APPROVED REQUESTS','OEM BUYER-APPROVED REQUESTS').replace('Forecasts shared with this partner','OEM forecasts shared with this partner')};
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target||!target.dataset.action.startsWith('lab-'))return;e.preventDefault();e.stopImmediatePropagation();const action=target.dataset.action;try{if(action.startsWith('lab-nav-'))return labGo(action.slice(8));if(action.startsWith('lab-line-'))return lineDetail(action.slice(9));if(action.startsWith('lab-job-'))return jobDetail(action.slice(8));if(action.startsWith('lab-component-'))return componentEditor(action.slice(14));if(action.startsWith('lab-fleet-')){fleetTab=action.slice(10);return render()}if(action.startsWith('lab-room-')){labTab=action.slice(9);labPage=1;return render()}if(action.startsWith('lab-horizon-')){horizon=Number(action.slice(12));return render()}if(action.startsWith('lab-air-request-')){const rest=action.slice(16),split=rest.indexOf('-');return airlineRequest(rest.slice(0,split),rest.slice(split+1))}if(action.startsWith('lab-air-review-'))return airlineReview(action.slice(15));if(action.startsWith('lab-air-supplier-')){const a=lab.actions.find(a=>a.id===action.slice(17));if(!a)return;state.supplier=a.supplier;state.role='Supplier';close();save();render();window.scrollTo({top:document.documentElement.scrollHeight,behavior:'instant'});return}if(action.startsWith('lab-air-respond-'))return airlineRespond(action.slice(16));if(action.startsWith('lab-air-approve-')){const a=lab.actions.find(a=>a.id===action.slice(16));if(!a||a.status!=='Buyer review')return;a.status='Awaiting supplier';close();return labEvent(a.id+' buyer-approved; supplier acceptance still required.')}if(action.startsWith('lab-air-reject-')||action.startsWith('lab-air-decline-')){const decline=action.startsWith('lab-air-decline-'),a=lab.actions.find(a=>a.id===action.slice(decline?16:15));if(!a)return;if(decline&&(state.role!=='Supplier'||state.supplier!==a.supplier||a.status!=='Awaiting supplier'))return;if(!decline&&a.status!=='Buyer review')return;a.status=decline?'Declined':'Rejected';close();return labEvent(a.id+' '+a.status.toLowerCase()+'.')}switch(action){case'lab-method':return methodDialog();case'lab-pitch':return pitchDialog();case'lab-demo-oem':lab.org='OEM';lab.uplift=20;lab.delay=30;lab.earlyMaterial=false;close();state.view='Metrics & Forecasting';state.role='Buyer';return labEvent('Loaded OEM stress scenario: +20% demand, +30 days disruption.');case'lab-airline-home':lab.org='Airline';labGo('Control tower');return;case'lab-baseline':lab.uplift=0;lab.delay=0;lab.earlyMaterial=false;lab.utilization=1;return labEvent('Restored baseline analytical assumptions; source records and actions retained.');case'lab-page-prev':labPage=Math.max(1,labPage-1);return render();case'lab-page-next':labPage++;return render();case'lab-table-export':{const rows=roomRecords();return labDownload('skysupply-'+labTab+'-synthetic.csv',csvText(rows,Object.keys(rows[0]||{})))}case'lab-inventory-sample':return labDownload('skysupply-inventory-sample.csv',csvText(inventoryCSV(),inventoryHeaders));case'lab-inventory-apply':if(inventoryPreview&&!inventoryPreview.errors.length){applyInventory(inventoryPreview.patches);inventoryPreview=null;return labEvent('Applied reviewed synthetic inventory snapshot locally.')}return;case'lab-sync':return syncPreview();case'lab-sync-apply':{const inv=D.inventory.find(r=>r.org===lab.org&&r.partId===(lab.org==='OEM'?'housing':'apu')),x=A.inventory(D,lab,lab.org,inv.partId),o=D.orders.find(o=>o.org===lab.org&&o.partId===inv.partId),f=A.forecast(D,lab,o,state);applyInventory({[inv.id]:{onHand:Math.max(x.reserved+x.held,x.onHand-1),reserved:x.reserved,held:x.held,updated:A.BASE}});lab.poOverrides[o.id]={...lab.poOverrides[o.id],promised:A.add(f.row.promised,7)};lab.syncCount++;close();return labEvent('Applied staged fictional ERP update #'+lab.syncCount+'; no external system contacted.')}case'lab-scored':{const b=A.backtest(D);return open('Inspect the synthetic holdout',`<p>${b.count} test records scored. Only training receipts available at each test order date are used. Supplier-promise MAE: ${b.promiseMae.toFixed(1)} days. Estimator MAE: ${b.mae.toFixed(1)} days.</p><div class="table-scroll"><table><thead><tr><th>Holdout record</th><th>Known training receipts</th><th>Actual lead</th><th>Promise</th><th>Estimated lead</th><th>Absolute error</th></tr></thead><tbody>${b.rows.map(r=>`<tr><td>${r.id}</td><td>${r.trainCount}</td><td>${r.actualLead}d</td><td>${r.promisedLead}d</td><td>${r.estimate}d</td><td>${r.error}d</td></tr>`).join('')}</tbody></table></div><p class="fine-print">These are generated records. This result is reproducible within the demo, not independent evidence of performance on real suppliers.</p>`)}case'lab-export':return labDownload('skysupply-erp-analytics-scenario.json',JSON.stringify({manifest:D.manifest,network:state,analytics:lab,sourcing:typeof sourcing!=='undefined'?sourcing:null,syntheticListings:typeof SkySourcing!=='undefined'?SkySourcing.offers(D):[],syntheticDataset:D,computedBacktest:A.backtest(D)},null,2),'application/json');case'lab-reset-start':return open('Reset analytics and airline scenario?',`<p>This clears analytical assumptions, inventory imports, airline requests and component-target edits. OEM network commitments stay as they are. Export first to keep a readable record.</p><div class="dialog-actions">${btn('Cancel','close')}${btn('Reset analytics only','lab-reset-confirm','primary','refresh')}</div>`);case'lab-reset-confirm':for(const id of Object.keys(lab.inventoryOverrides)){const inv=D.inventory.find(r=>r.id===id),n=state.parts.find(p=>p.id===inv?.partId);if(inv?.org==='OEM'&&n)n.stock=inv.onHand-inv.reserved-inv.held}lab=A.initial();lab.installedOverrides={};inventoryPreview=null;close();state.view='Control tower';state.role='Buyer';return labEvent('Analytics and airline scenario reset; OEM agreements retained.')}}catch(err){toast(err.message)}},true);
document.addEventListener('submit',e=>{const form=e.target;if(!['lab-scenario','lab-room-search','lab-component','air-request','air-response'].includes(form.id))return;e.preventDefault();e.stopImmediatePropagation();if(!form.reportValidity())return;const fd=new FormData(form);try{if(form.id==='lab-scenario'){lab.uplift=Number(fd.get('uplift'));lab.delay=Number(fd.get('delay'));lab.earlyMaterial=lab.org==='OEM'?fd.has('earlyMaterial'):lab.earlyMaterial;lab.utilization=fd.has('utilization')?Number(fd.get('utilization')):lab.utilization;return labEvent('Recalculated scenario from fictional ERP records and selected assumptions.')}if(form.id==='lab-room-search'){labQuery=String(fd.get('query')).trim();labPage=1;return render()}if(form.id==='lab-component'){lab.installedOverrides[form.dataset.id]=Object.fromEntries([...fd.entries()].map(([k,v])=>[k,Number(v)]));close();return labEvent('Saved fictional component planning targets; reorder dates recalculated.')}if(form.id==='air-request'){const a=A.addAirlineAction(D,lab,form.dataset.job,form.dataset.kind,Number(fd.get('qty')),String(fd.get('owner')),fd.has('days')?Number(fd.get('days')):null);close();lab.org='Airline';state.role='Buyer';state.view='Actions';return labEvent(a.id+' created for airline buyer review; no coverage added.')}if(form.id==='air-response'){const a=lab.actions.find(a=>a.id===form.dataset.id);if(!a||a.status!=='Awaiting supplier'||state.role!=='Supplier'||state.supplier!==a.supplier)return;a.eta=String(fd.get('eta'));a.status='Confirmed';close();return labEvent(a.id+' accepted in the scenario; job-specific expected coverage recalculated.')}}catch(err){toast(err.message)}},true);
document.addEventListener('change',async e=>{if(e.target.id==='organization'){lab.org=e.target.value;if(typeof sourcing!=='undefined'&&sourcing.tour?.org!==lab.org){sourcing.tour=null;sourceSave()}if((lab.org==='OEM'&&state.view==='Fleet & maintenance')||(lab.org==='Airline'&&state.view==='Demand & commitments'))state.view='Control tower';labQuery='';labPage=1;state.role='Buyer';labSave();save();render();window.scrollTo({top:0,behavior:'instant'})}if(e.target.id==='lab-inventory-file'&&e.target.files[0]){try{const file=e.target.files[0];if(file.size>500000)throw Error('Use an inventory CSV under 500 KB.');inventoryPreview=A.validateInventory(D,readCSV(await file.text()))}catch(err){inventoryPreview={errors:[err.message],patches:{}}}render();toast(inventoryPreview.errors.length?'Inventory CSV needs correction.':'CSV validated. Review before applying.')}});
document.addEventListener('input',e=>{if(e.target.form?.id==='air-request'&&e.target.name==='days')$('#air-rental-expense').textContent=money(Number(e.target.value)*1200+1100);if(e.target.form?.id==='lab-scenario'&&e.target.name==='uplift')$('#lab-uplift-label').textContent=e.target.value+'%'});
ensureNetworkCatalog();labSave();save();render();
